          "unit_price": {
            "$ref": "meta_schema.json#/definitions/FieldNumber"
          },
          "total_price": {
            "$ref": "meta_schema.json#/definitions/FieldNumber"
          }
        },
        "required": [
          "item_name",
          "total_price"
        ]
      }
    }
  },
  "required": [
    "document_type",
    "store_name",
    "invoice_number",
    "date_time",
    "total_payable"
  ]
}

